SELECT ast13_book_depn_id AS book_depn_id , ast13_item_type AS item_type , ast13_pur_date AS pur_date , ast13_item_nm AS item_name , ast13_note AS note , ast13_pur_amt AS pur_amt , ast13_corp_nm AS corp_name , ast13_corp_tel AS corp_tel , ast13_retire_date AS retire_date , ast13_item_s_class_cd AS item_s_class_code , ast13_pur_tr_id AS pur_tr_id FROM ( SELECT a.* , ast01_class_tree_nm AS ast13_item_nm , f_ast_class_tree_nm_allpath2(ast13_ast_class_tree_id) AS ast13_item_full_nm , ast01_item_s_class_cd AS ast13_item_s_class_cd , ast06_note AS ast13_note , sys15_corp_nm AS ast13_corp_nm , sys15_tel AS ast13_corp_tel , CONCAT( f_cdnm('ItemLClassCode', ast01_item_l_class_cd, ast13_company_id, ast13_pur_date) , '-'||f_cdnm('ItemMClassCode', ast01_item_m_class_cd, ast13_company_id, ast13_pur_date) , CASE WHEN substr(ast01_item_s_class_cd,5) = '99' THEN '' ELSE '-'||f_cdnm('ItemSClassCode', ast01_item_s_class_cd, ast13_company_id, ast13_pur_date) END ) AS ast13_item_type FROM ast13_book_depn a INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast13_ast_class_tree_id LEFT OUTER JOIN ast06_tr ON ast06_tr_id = ast13_pur_tr_id LEFT OUTER JOIN sys15_corp ON sys15_corp_id = ast06_corp_id WHERE ast13_company_id = #{companyId} AND ast13_depn_date = ( SELECT MAX(ast13_depn_date) FROM ast13_book_depn b WHERE b.ast13_company_id = a.ast13_company_id AND b.ast13_pur_tr_id = a.ast13_pur_tr_id AND b.ast13_depn_date <= #{depnDate} ) AND COALESCE(ast01_item_l_class_cd,'') ILIKE #{itemLClassCode}
AND COALESCE(ast13_retire_date,'9999-12-31') > #{depnDate}
) t WHERE CONCAT(ast13_item_type, ast13_item_full_nm, ast13_note, ast13_corp_nm) ILIKE '%'||#{searchText}||'%' ORDER BY ast13_item_type collate "ko_KR.utf8" DESC , ast13_pur_date , ast13_item_nm collate "ko_KR.utf8" ASC

