 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}

mapper.select:
SELECT ast13_book_depn_id AS book_depn_id , ast13_account_type_nm AS account_type_name , ast13_item_type AS item_type , ast13_item_nm AS item_name , ast13_item_full_nm AS item_full_name , ast13_note AS note , ast13_pur_date AS pur_date , ast13_pur_amt AS pur_amt , ast13_non_deduct_tax AS non_deduct_tax , ast13_month_depn_cost AS month_depn_cost , ast13_depn_cost AS depn_cost , ast13_acm_depn_cost AS acm_depn_cost , ast13_rem_depn_cost AS rem_depn_cost , ast13_retire_date AS retire_date , ast13_pur_tr_id AS pur_tr_id FROM ( SELECT * , CASE WHEN COALESCE(ast01_depn_type,'0') = '0' THEN 0 ELSE ast13_pur_amt + ast13_non_deduct_tax - COALESCE(ast13_acm_depn_cost,0) END as ast13_rem_depn_cost FROM ( SELECT CAST(#{depnDate} AS date) as ast13_depn_date , CASE WHEN to_char(ast13_depn_date,'YYYYMM') = to_char(CAST(#{depnDate} AS date),'YYYYMM') THEN ast13_month_depn_cost ELSE 0 END as ast13_month_depn_cost , CASE WHEN to_char(ast13_depn_date,'YYYY') = to_char(CAST(#{depnDate} AS date),'YYYY') THEN ast13_depn_cost ELSE 0 END as ast13_depn_cost , f_cdnm('ItemLClassCode', ast01_item_l_class_cd, ast13_company_id, ast13_pur_date) ||'-'||f_cdnm('ItemMClassCode', ast01_item_m_class_cd, ast13_company_id, ast13_pur_date) ||CASE WHEN substr(ast01_item_s_class_cd,5) = '99' THEN '' ELSE '-'||f_cdnm('ItemSClassCode', ast01_item_s_class_cd, ast13_company_id, ast13_pur_date) END ast13_item_type , ast01_class_tree_nm as ast13_item_nm , f_ast_class_tree_nm_allpath2(ast13_ast_class_tree_id) as ast13_item_full_nm , f_cdnm('AccountType', ast01_account_type, ast13_company_id, ast13_pur_date) as ast13_account_type_nm , COALESCE(( SELECT ast16_apply_non_deduct_tax FROM ast16_non_deduct_tax WHERE ast16_pur_tr_id = ast13_pur_tr_id AND ast16_apply_date <= #{depnDate} ORDER BY ast16_apply_date DESC LIMIT 1 ),0) as ast13_non_deduct_tax , ast06_note as ast13_note , ast13_book_depn_id, ast13_pur_tr_id, ast13_pur_date, ast13_pur_amt, ast13_retire_date, ast13_acm_depn_cost, ast01_depn_type FROM ast13_book_depn LEFT OUTER JOIN ast06_tr ON ast06_tr_id = ast13_pur_tr_id INNER JOIN ast01_class_tree ON ( ast01_class_tree_id = ast13_ast_class_tree_id AND ast01_depn_type IS NOT NULL ) WHERE ast13_company_id = #{companyId} AND (ast13_pur_tr_id, ast13_depn_date) IN ( SELECT ast13_pur_tr_id, MAX(ast13_depn_date) FROM ast13_book_depn WHERE ast13_company_id = #{companyId} AND ast13_depn_date <= #{depnDate} GROUP BY ast13_pur_tr_id ) AND COALESCE(ast01_item_l_class_cd,'') ILIKE #{itemLClassCode}
AND COALESCE(ast13_retire_date,'9999-12-31') > #{depnDate}
) t ) t2 WHERE CONCAT(ast13_account_type_nm, ast13_item_type, ast13_item_full_nm, ast13_note) ILIKE '%'||#{searchText}||'%' ORDER BY ast13_account_type_nm collate "ko_KR.utf8" asc , ast13_item_type collate "ko_KR.utf8" desc , ast13_pur_date , ast13_item_nm collate "ko_KR.utf8" asc
